A holomorphic function $f\colon (\mathbb{C}^n,0)\to (\mathbb{C},0)$
is said a {\bf generalized semi-Brieskorn-Pham} if there are a holomorphic diffeomorphism $\phi\colon (\mathbb{C}^n,0)\to (\mathbb{C}^n,0)$, a holomorphic function $h\colon (\mathbb{C}^n,0)\to (\mathbb{C},0)$, and positive integer numbers $k, a_1,...,a_{k-1}$ and $a_k$ such that 
\begin{enumerate}
\item $a_1\leq a_2\leq ....\leq a_k$;
\item ${\rm ord}_0h>a_k$;
 \item $f\circ \phi(z_1,...,z_n)=z_1^{a_1}+...+z_k^{a_k}+h(z_1,...,z_n)$ for all $z=(z_1,...,z_n)$ close to $0$.
\end{enumerate}
In this case, if $a_1=1$, we define $m_1(f)=1$, and if $a_1>1$, we define $m_1(f):=\max\{i;a_i=a_1\}$. When $f$ is a generalized semi-Brieskorn-Pham function, we also say that $V(f)$ is a {\bf generalized semi-Brieskorn-Pham hypersurface}.

\label{exam:linear_cone}
\begin{itemize}
    \item [a)] Any holomorphic function $f\colon (\mathbb{C}^n,0)\to (\mathbb{C},0)$ such that $C(V(f),0)$ is a linear subspace is a generalized semi-Brieskorn-Pham function;
    \item [b)] Any irreducible holomorphic function $f\colon (\mathbb{C}^2,0)\to (\mathbb{C},0)$ is a generalized semi-Brieskorn-Pham function;
    \item [c)] If $f\colon (\mathbb{C}^n,0)\to (\mathbb{C},0)$ is a generalized semi-Brieskorn-Pham function, then $\tilde f\colon (\mathbb{C}^{n+1},0)\to (\mathbb{C},0)$ given by $\tilde f(t,x)=t^m+f(x)$ is a generalized semi-Brieskorn-Pham function as well. In particular, the surfaces of the type $\{(x,y,z)\in \mathbb{C}^3;x^m+f(y,z)=0\}$ with $f\colon (\mathbb{C}^2,0)\to (\mathbb{C},0)$ being an irreducible holomorphic function, studied by Mendris and N\'emethi in \cite{MendrisN:2005}, are generalized semi-Brieskorn-Pham hypersurfaces.
\end{itemize}

\label{prop:formula_euler_charac_monodromy}
Let $f: (\mathbb{C}^{n}, 0) \to (\mathbb{C}, 0)$ be a reduced holomorphic function-germ and $m = m(V(f), 0)$. Let $h_f$ be the monodromy of the Milnor fiber of $f$, and let $F_{in(f)}$ be the Milnor fiber of the initial homogeneous part of $f$. Then
\[ \Lambda(h_f^m) = \chi(F_{in(f)}). \]

\label{cor:corank_non-isolated_one}
	Let  $f_t\colon (\mathbb{C}^n,0)\to (\mathbb{C},0)$ be a continuous family of germs of holomorphic functions with a (possibly non-isolated) critical point at the origin. Assume that for some coordinate system on $\mathbb{C}^n$, all L\^e numbers of $f_t$ are independent of $t$.
	Then the corank of $f_t$ is independent of $t$.

\label{cor:corank_non-isolated_two}
	Let  $f_t\colon (\mathbb{C}^n,0)\to (\mathbb{C},0)$ be a continuous family of germs of holomorphic functions with a (possibly non-isolated) critical point at the origin. Assume that the embedded topological type of $f_t$ is independent of $t$, and each $f_t$ has aligned singularities.
	Then the corank of $f_t$ is independent of $t$.
